// Resume a execução do Agente: chamadas ao modelo, tokens e ferramentas, em ordem.
const exec = $input.first().json;
const runData = exec.data?.resultData?.runData ?? {};
let chamadas = 0, entrada = 0, saida = 0;
const modelos = {}, extras = {}, passos = [];
for (const [nome, runs] of Object.entries(runData)) {
  for (const r of runs) {
    const lm = r.data?.ai_languageModel?.[0]?.[0]?.json;
    if (lm?.tokenUsage) {
      chamadas++;
      entrada += lm.tokenUsage.promptTokens || 0;
      saida += lm.tokenUsage.completionTokens || 0;
      modelos[nome] = (modelos[nome] || 0) + 1;
      for (const [k, v] of Object.entries(lm.tokenUsage)) {
        if (!['promptTokens', 'completionTokens', 'totalTokens'].includes(k) && typeof v === 'number') extras[k] = (extras[k] || 0) + v;
      }
      for (const [k, v] of Object.entries(r.metadata?.tracing ?? {})) {
        if (k.includes('cache') && typeof v === 'number') extras[k] = (extras[k] || 0) + v;
      }
    }
    if (r.data?.ai_tool) passos.push({ nome, inicio: r.startTime });
  }
}
passos.sort((a, b) => a.inicio - b.inicio);
return [{ json: {
  output: $('Execução a medir').first().json.output,
  exec_id: exec.id,
  status: exec.status,
  chamadas, modelos,
  ferramentas: passos.map(p => p.nome),
  entrada, saida, extras,
} }];
